# =============================================================================
# Shared Configuration
# =============================================================================
# This file is symlinked into each app directory to provide common variables
# and provider configuration. Each app has its own state file.
#
# Secret Management:
# - State encryption passphrase: Must remain as TF_VAR (needed before providers init)
# - All other secrets: Fetched from 1Password via onepassword provider
# =============================================================================

# -----------------------------------------------------------------------------
# State Encryption (Required as TF_VAR - runs before providers)
# -----------------------------------------------------------------------------

variable "state_encryption_passphrase" {
  description = "Passphrase for encrypting state files (from 1Password: op://homelab/opentofu/password)"
  type        = string
  sensitive   = true
}

# -----------------------------------------------------------------------------
# Proxmox Configuration
# -----------------------------------------------------------------------------

variable "proxmox_endpoint" {
  description = "Proxmox API endpoint URL"
  type        = string
  default     = "https://192.168.1.215:8006"
}

variable "proxmox_node" {
  description = "Proxmox node name"
  type        = string
  default     = "pve"
}

variable "proxmox_ssh_host" {
  description = "Proxmox host SSH address (for configuring privileged containers)"
  type        = string
  default     = "192.168.1.215"
}

# -----------------------------------------------------------------------------
# SSH Configuration
# -----------------------------------------------------------------------------

variable "ssh_private_key_path" {
  description = "Path to SSH private key"
  type        = string
  default     = "~/.ssh/homelab_ed25519"
}

variable "ssh_public_key_path" {
  description = "Path to SSH public key"
  type        = string
  default     = "~/.ssh/homelab_ed25519.pub"
}

# -----------------------------------------------------------------------------
# Storage & Network Defaults
# -----------------------------------------------------------------------------

variable "default_storage" {
  description = "Default storage for LXC containers"
  type        = string
  default     = "tank"
}

variable "default_bridge" {
  description = "Default network bridge"
  type        = string
  default     = "vmbr0"
}

variable "lxc_template" {
  description = "Default LXC template (base Debian)"
  type        = string
  default     = "local:vztmpl/debian-13-standard_13.1-2_amd64.tar.zst"
}

variable "lxc_template_docker" {
  description = "LXC template with Docker pre-installed"
  type        = string
  default     = "local:vztmpl/debian-13-docker_1.0_amd64.tar.zst"
}

# -----------------------------------------------------------------------------
# Domain Configuration
# -----------------------------------------------------------------------------

variable "domain_internal" {
  description = "Internal domain suffix"
  type        = string
  default     = "homelab.rambtech.dev"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]+[a-z0-9]$", var.domain_internal))
    error_message = "Internal domain must be a valid domain name (e.g., homelab.example.com)."
  }
}

variable "domain_public" {
  description = "Public domain"
  type        = string
  default     = "rambtech.dev"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]+[a-z0-9]$", var.domain_public))
    error_message = "Public domain must be a valid domain name (e.g., example.com)."
  }
}

# -----------------------------------------------------------------------------
# Cloudflare Configuration (IDs only - tokens from 1Password)
# -----------------------------------------------------------------------------

variable "cloudflare_account_id" {
  description = "Cloudflare account ID"
  type        = string
  default     = ""
}

variable "cloudflare_zone_id" {
  description = "Cloudflare zone ID"
  type        = string
  default     = ""
}

variable "cloudflare_tunnel_id" {
  description = "Cloudflare tunnel ID"
  type        = string
  default     = ""
}

# -----------------------------------------------------------------------------
# DNS Mode Configuration (Home/Travel)
# -----------------------------------------------------------------------------

variable "dns_mode" {
  description = "DNS resolution mode: 'home' uses LAN IPs (192.168.1.x), 'travel' uses container IPs (10.100.x.x) for Tailscale routing"
  type        = string
  default     = "home"

  validation {
    condition     = contains(["home", "travel"], var.dns_mode)
    error_message = "dns_mode must be either 'home' or 'travel'"
  }
}

# -----------------------------------------------------------------------------
# Computed Locals
# -----------------------------------------------------------------------------

locals {
  ssh_public_key = file(var.ssh_public_key_path)
}

# =============================================================================
# 1Password Provider Configuration
# =============================================================================
# This file provides direct 1Password integration for secret management.
# Secrets are fetched at plan/apply time using the 1Password CLI.
#
# Authentication: Uses 1Password CLI with biometric unlock
# Ensure `op` CLI v2.23.0+ is installed and signed in
#
# Usage: Symlink this file to any app that needs 1Password secrets
#   ln -s ../../../onepassword.tf tofu/apps/<app>/onepassword.tf
# =============================================================================

# -----------------------------------------------------------------------------
# 1Password Vault Reference
# -----------------------------------------------------------------------------

data "onepassword_vault" "homelab" {
  name = "homelab"
}

# -----------------------------------------------------------------------------
# Core Infrastructure Secrets
# -----------------------------------------------------------------------------

# OpenTofu state encryption and Proxmox credentials
data "onepassword_item" "opentofu" {
  vault = data.onepassword_vault.homelab.uuid
  title = "opentofu"
}

# -----------------------------------------------------------------------------
# Cloudflare Secrets
# -----------------------------------------------------------------------------

data "onepassword_item" "cloudflare" {
  vault = data.onepassword_vault.homelab.uuid
  title = "Cloudflare"
}

# -----------------------------------------------------------------------------
# Monitoring Secrets
# -----------------------------------------------------------------------------

data "onepassword_item" "grafana" {
  vault = data.onepassword_vault.homelab.uuid
  title = "grafana"
}

data "onepassword_item" "discord_webhook" {
  vault = data.onepassword_vault.homelab.uuid
  title = "discord-alertmanager-webhook"
}

data "onepassword_item" "uptime_kuma" {
  vault = data.onepassword_vault.homelab.uuid
  title = "uptime-kuma"
}

data "onepassword_item" "alloy_telemetry" {
  vault = data.onepassword_vault.homelab.uuid
  title = "alloy-telemetry"
}

# -----------------------------------------------------------------------------
# Container Management Secrets (Pulse + Arcane)
# -----------------------------------------------------------------------------

data "onepassword_item" "pulse" {
  vault = data.onepassword_vault.homelab.uuid
  uuid  = "zi3pssvujqcc2zmshihgkmfkju" # "pulse" (lowercase LOGIN item)
}

data "onepassword_item" "arcane" {
  vault = data.onepassword_vault.homelab.uuid
  uuid  = "kqujk6bc3wloojsmulzbrdaaie" # "arcane" (lowercase LOGIN item)
}

# -----------------------------------------------------------------------------
# Authentik Secrets (Identity Provider)
# -----------------------------------------------------------------------------

data "onepassword_item" "authentik" {
  vault = data.onepassword_vault.homelab.uuid
  title = "authentik"
}

# -----------------------------------------------------------------------------
# Agent Tokens (per-LXC tokens stored in centralized items)
# -----------------------------------------------------------------------------
# Structure: One item per agent type with sections for each LXC
#   pulse-agents:
#     n8n.token, immich.token, jellyfin.token, ...
#   arcane-agents:
#     n8n.bootstrap_token, immich.bootstrap_token, ...

data "onepassword_item" "pulse_agents" {
  vault = data.onepassword_vault.homelab.uuid
  title = "pulse-agents"
}

data "onepassword_item" "arcane_agents" {
  vault = data.onepassword_vault.homelab.uuid
  title = "arcane-agents"
}

# -----------------------------------------------------------------------------
# Helper Locals - Flatten 1Password fields for easy access
# -----------------------------------------------------------------------------
# The 1Password provider returns fields in a nested structure.
# Custom fields are inside section blocks.

locals {
  # Flatten all section fields from opentofu item into a map by label
  _opentofu_section_fields = merge([
    for s in data.onepassword_item.opentofu.section : {
      for f in s.field : f.label => f.value
    }
  ]...)

  # Flatten all section fields from cloudflare item into a map by label
  _cloudflare_section_fields = merge([
    for s in data.onepassword_item.cloudflare.section : {
      for f in s.field : f.label => f.value
    }
  ]...)

  # Flatten all section fields from arcane item into a map by label
  _arcane_section_fields = merge([
    for s in data.onepassword_item.arcane.section : {
      for f in s.field : f.label => f.value
    }
  ]...)

  # Flatten alloy-telemetry section fields
  _alloy_telemetry_fields = merge([
    for s in try(data.onepassword_item.alloy_telemetry.section, []) : {
      for f in try(s.field, []) : f.label => f.value
    }
  ]...)

  # Flatten authentik section fields
  _authentik_section_fields = merge([
    for s in try(data.onepassword_item.authentik.section, []) : {
      for f in try(s.field, []) : f.label => f.value
    }
  ]...)

  # Flatten pulse-agents sections into map: { "n8n" = { "token" = "xxx" }, ... }
  _pulse_agents_by_lxc = {
    for s in try(data.onepassword_item.pulse_agents.section, []) : s.label => {
      for f in try(s.field, []) : f.label => f.value
    }
  }

  # Flatten arcane-agents sections into map: { "n8n" = { "bootstrap_token" = "xxx" }, ... }
  _arcane_agents_by_lxc = {
    for s in try(data.onepassword_item.arcane_agents.section, []) : s.label => {
      for f in try(s.field, []) : f.label => f.value
    }
  }

  # 1Password secrets - access via local.op.<secret_name>
  op = {
    # State encryption passphrase (main password field)
    state_encryption_passphrase = data.onepassword_item.opentofu.password

    # Proxmox API token (custom field in section)
    proxmox_api_token = lookup(local._opentofu_section_fields, "proxmox_api_token", "")

    # Cloudflare (custom fields in sections + standard fields)
    cloudflare_email        = data.onepassword_item.cloudflare.username
    cloudflare_tunnel_token = lookup(local._cloudflare_section_fields, "tunnel_token", "")
    cloudflare_api_token    = lookup(local._cloudflare_section_fields, "ddns_api_token", lookup(local._cloudflare_section_fields, "Api token - traefik", ""))
    cloudflare_dns_token    = lookup(local._cloudflare_section_fields, "Api token - traefik", "")

    # Monitoring
    grafana_admin_password  = data.onepassword_item.grafana.password
    discord_webhook_url     = data.onepassword_item.discord_webhook.credential
    uptime_kuma_username    = data.onepassword_item.uptime_kuma.username
    uptime_kuma_password    = data.onepassword_item.uptime_kuma.password

    # Container Management (Pulse + Arcane)
    pulse_admin_user     = data.onepassword_item.pulse.username
    pulse_admin_password = data.onepassword_item.pulse.password
    arcane_encryption_key = lookup(local._arcane_section_fields, "encryption_key", "")
    arcane_jwt_secret     = lookup(local._arcane_section_fields, "jwt_secret", "")

    # Alloy Telemetry (for Loki/Prometheus push auth)
    alloy_telemetry_username = data.onepassword_item.alloy_telemetry.username
    alloy_telemetry_password = data.onepassword_item.alloy_telemetry.password
    alloy_telemetry_htpasswd = lookup(local._alloy_telemetry_fields, "htpasswd", "")

    # Authentik (Identity Provider)
    authentik_admin_user        = data.onepassword_item.authentik.username
    authentik_admin_password    = data.onepassword_item.authentik.password
    authentik_secret_key        = lookup(local._authentik_section_fields, "secret_key", "")
    authentik_postgres_password = lookup(local._authentik_section_fields, "postgres_password", "")
    authentik_google_client_id     = lookup(local._authentik_section_fields, "google_client_id", "")
    authentik_google_client_secret = lookup(local._authentik_section_fields, "google_client_secret", "")
  }

  # Agent tokens by LXC name - access via local.agent_tokens["n8n"].pulse_token
  # Each entry has .pulse_token and .arcane_bootstrap_token
  agent_tokens = {
    for lxc_name in distinct(concat(
      keys(local._pulse_agents_by_lxc),
      keys(local._arcane_agents_by_lxc)
    )) : lxc_name => {
      pulse_token            = try(local._pulse_agents_by_lxc[lxc_name]["token"], "")
      arcane_bootstrap_token = try(local._arcane_agents_by_lxc[lxc_name]["bootstrap_token"], "")
    }
  }
}

# =============================================================================
# State Encryption
# =============================================================================

variable "state_encryption_passphrase" {
  description = "Passphrase for encrypting state files (use TF_VAR_state_encryption_passphrase)"
  type        = string
  sensitive   = true
}

# =============================================================================
# Proxmox Configuration
# =============================================================================

variable "proxmox_endpoint" {
  description = "Proxmox API endpoint URL"
  type        = string
  default     = "https://homelab:8006"
}

variable "proxmox_username" {
  description = "Proxmox username (user@realm or API token)"
  type        = string
  default     = "root@pam"
}

variable "proxmox_password" {
  description = "Proxmox password or API token secret"
  type        = string
  sensitive   = true
}

variable "proxmox_node" {
  description = "Proxmox node name"
  type        = string
  default     = "homelab"
}

variable "ssh_private_key_path" {
  description = "Path to SSH private key for Proxmox access"
  type        = string
  default     = "~/.ssh/homelab_ed25519"
}

variable "ssh_public_key_path" {
  description = "Path to SSH public key for LXC provisioning"
  type        = string
  default     = "~/.ssh/homelab_ed25519.pub"
}

# =============================================================================
# Cloudflare Configuration
# =============================================================================

variable "cloudflare_api_token" {
  description = "Cloudflare API token with DNS and Tunnel permissions"
  type        = string
  sensitive   = true
  default     = ""
}

variable "cloudflare_account_id" {
  description = "Cloudflare account ID"
  type        = string
  default     = ""
}

variable "cloudflare_zone_id" {
  description = "Cloudflare zone ID for rambtech.dev"
  type        = string
  default     = ""
}

variable "cloudflare_tunnel_id" {
  description = "Existing Cloudflare tunnel ID (if using tunnel exposure)"
  type        = string
  default     = ""
}

# =============================================================================
# Domain Configuration
# =============================================================================

variable "domain_internal" {
  description = "Internal domain suffix"
  type        = string
  default     = "homelab.rambtech.dev"
}

variable "domain_tailnet" {
  description = "Tailscale domain suffix"
  type        = string
  default     = "tailnet.rambtech.dev"
}

variable "domain_public" {
  description = "Public domain"
  type        = string
  default     = "rambtech.dev"
}

# =============================================================================
# Infrastructure Defaults
# =============================================================================

variable "default_storage" {
  description = "Default storage for LXC containers"
  type        = string
  default     = "local-lvm"
}

variable "default_bridge" {
  description = "Default network bridge"
  type        = string
  default     = "vmbr0"
}

variable "lxc_template" {
  description = "Default LXC template to use"
  type        = string
  default     = "local:vztmpl/debian-13-standard_13.1-2_amd64.tar.zst"
}

