# =============================================================================
# Provider Versions and Configuration
# =============================================================================
# This file is symlinked into each app directory.
# Providers use secrets from 1Password via local.op.* (defined in onepassword.tf)
# =============================================================================

terraform {
  required_version = ">= 1.7.0"

  required_providers {
    proxmox = {
      source  = "bpg/proxmox"
      version = "~> 0.69"
    }
    onepassword = {
      source  = "1password/onepassword"
      version = "~> 2.1"
    }
    cloudflare = {
      source  = "cloudflare/cloudflare"
      version = "~> 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.5"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.2"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.12"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
    # Custom providers for file sync and docker compose management
    filesync = {
      source  = "darshan-rambhia/filesync"
      version = "~> 0.3"
    }
    remotedockercompose = {
      source  = "darshan-rambhia/remote-docker-compose-file"
      version = "~> 0.3"
    }
    ansible = {
      source  = "marshallford/ansible"
      version = "~> 0.9"
    }
    # Authentik provider for identity management
    authentik = {
      source  = "goauthentik/authentik"
      version = "~> 2024.12"
    }
    # SOPS provider for encrypted secrets
    sops = {
      source  = "carlpett/sops"
      version = "~> 1.1"
    }
  }

  # Encrypted local state - safe to commit to git
  # Note: state_encryption_passphrase must be provided via TF_VAR
  # because encryption runs before providers are initialized
  encryption {
    key_provider "pbkdf2" "main" {
      passphrase = var.state_encryption_passphrase
    }

    method "aes_gcm" "default" {
      keys = key_provider.pbkdf2.main
    }

    state {
      method   = method.aes_gcm.default
      enforced = true
    }

    plan {
      method   = method.aes_gcm.default
      enforced = true
    }
  }
}

# -----------------------------------------------------------------------------
# 1Password Provider
# -----------------------------------------------------------------------------
# Authentication via CLI with biometric unlock
# Requires: op CLI v2.23.0+, signed in account

provider "onepassword" {
  # Uses biometric authentication via 1Password CLI
  # Set OP_ACCOUNT env var or account field to your 1Password account URL
  account = "rambhia.1password.com"
}

# -----------------------------------------------------------------------------
# Proxmox Provider
# -----------------------------------------------------------------------------
# API token fetched from 1Password

provider "proxmox" {
  endpoint  = var.proxmox_endpoint
  api_token = local.op.proxmox_api_token
  insecure  = true

  ssh {
    agent       = true
    username    = "root"
    private_key = file(var.ssh_private_key_path)
  }
}

# -----------------------------------------------------------------------------
# Cloudflare Provider
# -----------------------------------------------------------------------------
# API token fetched from 1Password

provider "cloudflare" {
  api_token = local.op.cloudflare_api_token
}

# -----------------------------------------------------------------------------
# Filesync Provider
# -----------------------------------------------------------------------------
# SSH-based file synchronization to remote hosts

provider "filesync" {
  ssh_user                 = "root"
  ssh_key_path             = pathexpand(var.ssh_private_key_path)
  known_hosts_file         = pathexpand("~/.ssh/known_hosts")
  strict_host_key_checking = "accept-new"
}

# -----------------------------------------------------------------------------
# Remote Docker Compose Provider
# -----------------------------------------------------------------------------
# Manage Docker Compose stacks on remote hosts via SSH

provider "remotedockercompose" {
  ssh_user                 = "root"
  ssh_key_path             = pathexpand(var.ssh_private_key_path)
  known_hosts_file         = pathexpand("~/.ssh/known_hosts")
  strict_host_key_checking = "accept-new"
}

# -----------------------------------------------------------------------------
# Authentik Provider
# -----------------------------------------------------------------------------
# Manages authentik resources (applications, providers, sources)
# Token generated via: authentik admin -> System -> Tokens -> Create

provider "authentik" {
  url   = "https://auth.${var.domain_internal}"
  token = lookup(local._authentik_section_fields, "api_token", "")
}

# =============================================================================
# Shared Configuration
# =============================================================================
# This file is symlinked into each app directory to provide common variables
# and provider configuration. Each app has its own state file.
#
# Secret Management:
# - State encryption passphrase: Must remain as TF_VAR (needed before providers init)
# - All other secrets: Fetched from 1Password via onepassword provider
# =============================================================================

# -----------------------------------------------------------------------------
# State Encryption (Required as TF_VAR - runs before providers)
# -----------------------------------------------------------------------------

variable "state_encryption_passphrase" {
  description = "Passphrase for encrypting state files (from 1Password: op://homelab/opentofu/password)"
  type        = string
  sensitive   = true
}

# -----------------------------------------------------------------------------
# Proxmox Configuration
# -----------------------------------------------------------------------------

variable "proxmox_endpoint" {
  description = "Proxmox API endpoint URL"
  type        = string
  default     = "https://192.168.1.215:8006"
}

variable "proxmox_node" {
  description = "Proxmox node name"
  type        = string
  default     = "pve"
}

variable "proxmox_ssh_host" {
  description = "Proxmox host SSH address (for configuring privileged containers)"
  type        = string
  default     = "192.168.1.215"
}

# -----------------------------------------------------------------------------
# SSH Configuration
# -----------------------------------------------------------------------------

variable "ssh_private_key_path" {
  description = "Path to SSH private key"
  type        = string
  default     = "~/.ssh/homelab_ed25519"
}

variable "ssh_public_key_path" {
  description = "Path to SSH public key"
  type        = string
  default     = "~/.ssh/homelab_ed25519.pub"
}

# -----------------------------------------------------------------------------
# Storage & Network Defaults
# -----------------------------------------------------------------------------

variable "default_storage" {
  description = "Default storage for LXC containers"
  type        = string
  default     = "tank"
}

variable "default_bridge" {
  description = "Default network bridge"
  type        = string
  default     = "vmbr0"
}

variable "lxc_template" {
  description = "Default LXC template (base Debian)"
  type        = string
  default     = "local:vztmpl/debian-13-standard_13.1-2_amd64.tar.zst"
}

variable "lxc_template_docker" {
  description = "LXC template with Docker pre-installed"
  type        = string
  default     = "local:vztmpl/debian-13-docker_1.0_amd64.tar.zst"
}

# -----------------------------------------------------------------------------
# Domain Configuration
# -----------------------------------------------------------------------------

variable "domain_internal" {
  description = "Internal domain suffix"
  type        = string
  default     = "homelab.rambtech.dev"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]+[a-z0-9]$", var.domain_internal))
    error_message = "Internal domain must be a valid domain name (e.g., homelab.example.com)."
  }
}

variable "domain_public" {
  description = "Public domain"
  type        = string
  default     = "rambtech.dev"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]+[a-z0-9]$", var.domain_public))
    error_message = "Public domain must be a valid domain name (e.g., example.com)."
  }
}

# -----------------------------------------------------------------------------
# Cloudflare Configuration (IDs only - tokens from 1Password)
# -----------------------------------------------------------------------------

variable "cloudflare_account_id" {
  description = "Cloudflare account ID"
  type        = string
  default     = ""
}

variable "cloudflare_zone_id" {
  description = "Cloudflare zone ID"
  type        = string
  default     = ""
}

variable "cloudflare_tunnel_id" {
  description = "Cloudflare tunnel ID"
  type        = string
  default     = ""
}

# -----------------------------------------------------------------------------
# DNS Mode Configuration (Home/Travel)
# -----------------------------------------------------------------------------

variable "dns_mode" {
  description = "DNS resolution mode: 'home' uses LAN IPs (192.168.1.x), 'travel' uses container IPs (10.100.x.x) for Tailscale routing"
  type        = string
  default     = "home"

  validation {
    condition     = contains(["home", "travel"], var.dns_mode)
    error_message = "dns_mode must be either 'home' or 'travel'"
  }
}

# -----------------------------------------------------------------------------
# Computed Locals
# -----------------------------------------------------------------------------

locals {
  ssh_public_key = file(var.ssh_public_key_path)
}

